(33502, 'esES', 'Tesoro: ídolo obsidiana tallado', '', '', '', '', '', '', '', '', 19865),
(33504, 'esES', 'Imagen: piedra de Fuego de chamán', '', '', '', '', '', '', '', '', 19865),
(33505, 'esES', 'Tesoro: huevo de quimera inquieto', '', '', '', '', '', '', '', '', 19865),
