(35311, 'esES', 'Misión de recompensa: Comandante Vallefont', '', '', '', '', '', '', '', '', 19865),
(35312, 'esES', 'Misión de recompensa: Asedio de Niuzao', '', '', '', '', '', '', '', '', 19865),
