(36295, 'esES', 'Phylarch the Evergreen B', '', '', '', '', '', '', '', '', 19865),
(36296, 'esES', 'Filarca el Perenne', 'Acepta el juramento de sangre de la maestra del acero Na''Shra.', '[PHYLARCH ACQUISITION TEXT GOES HERE]', '', '', 'Maestra del acero Na''Shra', '', '', '', 19865),
(36297, 'esES', 'Spires - Vignette Boss 016 - Festerbloom', '', '', '', '', '', '', '', '', 19865),
