(30218, 'esES', 'DEPRECATED', '', '', '', '', '', '', '', '', 19865),
(30219, 'esES', 'DEPRECATED', '', '', '', '', '', '', '', '', 19865),
(30220, 'esES', 'DEPRECATED', '', '', '', '', '', '', '', '', 19865),
(30221, 'esES', 'DEPRECATED', '', '', '', '', '', '', '', '', 19865),
