INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`, `AreaDescription`, `PortraitGiverText`, `PortraitGiverName`, `PortraitTurnInText`, `PortraitTurnInName`, `QuestCompletionLog`, `VerifiedBuild`) VALUES
(31924, 'esES', 'Narrok', 'Derrota a Narrok en un duelo de mascotas.', 'Deseo luchar una vez más. Estos jóvenes necesitan fortalecerse.', '', '', '', '', '', 'Habla con: Narrok.', 19865),
(31925, 'esES', 'Morulu el Ancestro', 'Derrota a Morulu el Ancestro en un duelo de mascotas.', 'He aprendido mucho desde nuestro último encuentro. ¿Deseas poner a prueba tus habilidades una vez más?', '', '', '', '', '', 'Habla con: Morulu el Ancestro.', 19865),
(31926, 'esES', 'Gran maestro Antari', 'Derrota al caballero de sangre Antari en un duelo de mascotas.', 'Te aprovechaste de mis errores la última vez y saliste $gvictorioso:victoriosa;. Esta vez no tendrás tanta suerte, $r.', '', '', '', '', '', 'Habla con: Caballero de sangre Antari.', 19865),
(31927, 'esES', 'Domadores de mascotas de duelo: Rasganorte', 'Derrota a Beegle Mechaexplosiva, a Jacob Casi Decapitado, a Okrut Dragostador y a Arcadón en un duelo de mascotas.', '¡Los más aguerridos de Terrallende han caído ante tu pericia, pero te espera Rasganorte a continuación!$B$BAhora debes derrotar a cuatro domadores: Beegle Mechaexplosiva, en el Fiordo Aquilonal; a Jacob Casi Decapitado, en el Bosque Canto de Cristal; a Okrut Dragostador, en el Cementerio de Dragones y a Arcadón, en Zul''drak.$B$BSi consigues superarlos a todos, ¡seguro que te desafía el Gran maestro de Rasganorte!', '', '', 'Audrey Burnhep', '¿Estás $gpreparado:preparada; para esto?', 'Audrey Burnhep', '', 19865),
(31928, 'esES', 'Gran maestro Payne', 'Derrota al mayor Payne en un duelo de mascotas.', 'Opino que mis colegas domadores han sido demasiado indulgentes con tu entrenamiento.$B$BLa auténtica doma de mascota requiere disciplina militar. Te concederé el honor de contemplar de primera mano el resultado de esa disciplina.$B$B¡Ven a los Campos del Torneo Argenta en Corona de Hielo para que vean en qué te puedes convertir!', '', '', 'Mayor Payne', '', '', 'Habla con: Mayor Payne.', 19865),
(31929, 'esES', 'Domadores de mascotas de duelo: Rasganorte', 'Derrota a Beegle Mechaexplosiva, a Jacob Casi Decapitado, a Okrut Dragostador y a Arcadón en un duelo de mascotas.', '¡Los más aguerridos de Terrallende han caído ante tu pericia, pero te espera Rasganorte a continuación!$B$BAhora debes derrotar a cuatro domadores: Beegle Mechaexplosiva, en el Fiordo Aquilonal; a Jacob Casi Decapitado, en el Bosque Canto de Cristal; a Okrut Dragostador, en el Cementerio de Dragones y a Arcadón, en Zul''drak.$B$BSi consigues superarlos a todos, ¡seguro que te desafía el Gran maestro de Rasganorte!', '', '', 'Varzok', 'Te espera tu mayor desafío hasta la fecha.', 'Varzok', '', 19865),
(31930, 'esES', 'Domadores de mascotas de duelo: Pandaria', 'Derrota a Hyuna de los Santuarios, a la granjera Nishi, a Mo''ruk, al Valiente Yon, al buscador Zusshi y al transitayermos Shu en duelos de mascotas.', 'Ahora debes enfrentarte a los domadores de mascotas más duros de todo Azeroth, $n. Viven en Pandaria, el campo de entrenamiento de los grandes maestros.$b$bHay seis grandes maestros que te quedan por derrotar: Hyuna de los Santuarios, en el Bosque de Jade; la granjera Nishi, en el Valle de los Cuatro Vientos; Mo''ruk, en la Espesura Krasarang; Valiente Yon, en la Cima Kun-Lai; el buscador Zusshi, en las Estepas de Tong Long, y el transitayermos Shu, en el Desierto del Pavor.$b$bSi crees que estás $gpreparado:preparada;, ¡busca a estos campeones y ponte a prueba contra ellos!', '', '', '', '¡El final está cerca!', 'Audrey Burnhep', '', 19865),
(31931, 'esES', 'Beegle Mechaexplosiva', 'Derrota a Beegle Mechaexplosiva en un duelo de mascotas.', 'Ayer uno de mis pollos voló por un momento, lo juro. ¡Lo estamos consiguiendo!$B$BOh, ¿quieres luchar otra vez?', '', '', '', '', '', 'Habla con: Beegle Mechaexplosiva.', 19865),
(31932, 'esES', 'Jacob Casi Decapitado', 'Derrota a Jacob Casi Decapitado en un duelo de mascotas.', 'Desafías mi sabiduría una y otra vez. ¿Qué es lo que te sigue trayendo a estos bosques?$B$BAh, quieres volver a enfrentarte a mí. Muy bien.', '', '', '', '', '', 'Habla con: Jacob Casi Decapitado.', 19865),
(31933, 'esES', 'Okrut Dragostador', 'Derrota a Okrut Dragostador en un duelo de mascotas.', '¿Te atreves a interrumpir nuestro trabajo? ¡Entonces debes volver a luchar conmigo! ¡Saca tus mascotas y te haré probar la furia de Grito Infernal!', '', '', '', '', '', 'Habla con: Okrut Dragostador.', 19865),
(31934, 'esES', 'Arcadón', 'Derrota a Arcadón en un duelo de mascotas.', 'A mí gustar luchar contigo. Tú no ser tan fácil como los demás. ¿Luchar otra vez?', '', '', '', '', '', 'Habla con: Arcadón.', 19865),
(31935, 'esES', 'Gran maestro Payne', 'Derrota al mayor Payne en un duelo de mascotas.', '$gEl:La; $c rebelde vuelve para poner a prueba su poder contra el de un gran maestro. ¡Esta vez tu valentía será tu perdición!', '', '', '', '', '', 'Habla con: Mayor Payne.', 19865),
(31936, 'esES', 'El sistema de irrigación de la "Princesa Jinyu"', 'Lleva el sistema de irrigación de la "Princesa Jinyu" al granjero Yoon en el Rancho Cantosol o El Mercado del Alcor.', '<La parte trasera de la caja muestra la caricatura de una doncella jinyu rodeada de texto publicitario.>$B$B"Hola, jardineros. ¿Se os secan las calabazas? ¿No os salen bien los repollos? ¿Vuestros puerros renguean y vuestros melones dan pena?$B$B¡Pues ya es hora de que os llevéis a casa a la Princesa Jinyu! Regará vuestro jardín como una dulce lluvia de primavera y aliviará esa sequía con un buen trago de..."$B$B<Así durante 6 párrafos.>', '', '', '', '', '', 'Lleva el sistema de irrigación de la "Princesa Jinyu" al granjero Yoon en el Rancho Cantosol o El Mercado del Alcor.', 19865),
(31937, 'esES', 'Pesticidas "Rey del Trueno"', 'Lleva los pesticidas "Rey del Trueno" al granjero Yoon en el Rancho Cantosol o El Mercado del Alcor.', '<Una imagen imponente de un mogu domina esta caja, lanzando su mirada sobre filas de texto en negrita.>$B$B"NO PERMITA QUE INSECTOS DÉBILES Y ASQUEROSOS INFECTEN SU GLORIOSA COSECHA. CONQUÍSTELOS CON EL PODER DEL REY DEL TRUENO Y PROTEJA SU LEGADO."$B$B<El resto del espacio lo ocupan dibujos de varios insectos gritando en su agonía o huyendo aterrorizados.>', '', '', '', '', '', 'Lleva los pesticidas "Rey del Trueno" al granjero Yoon en el Rancho Cantosol o El Mercado del Alcor.', 19865),
(31938, 'esES', 'El arado maestro "Abretierras"', 'Lleva el arado maestro "Abretierras" al granjero Yoon en el Rancho Cantosol o El Mercado del Alcor.', '<El dibujo de la caja representa a un granjero pandaren con un físico increíble que se alza orgulloso sobre un amplio surco empuñando un poderoso arado. Unos cachorros juegan sobre sus hombros y se columpian en sus musculosos brazos.$B$BA su lado, una estoica hembra, con un físico igual de idealizado, lleva con gracia una rebosante cornucopia sobre la cabeza al tiempo que le da una patada a un mur.>$b$b"El Abretierras. Domina la tierra. Domina tu vida."', '', '', '', '', '', 'Lleva el arado maestro "Abretierras" al granjero Yoon en el Rancho Cantosol o El Mercado del Alcor.', 19865),
(31939, 'esES', '[TEMP]', 'Planta y recolecta 4 zanahorias Jugoasaz. Se pueden comprar semillas de zanahorias Jugoasaz al mercader Campo Fértil en el Mercado del Alcor. Después de cultivar y cuidar de las plantas, debes esperar hasta el día siguiente para recoger zanahorias Jugoasaz maduras.', 'Muy bien, $gamigo:amiga; ¡todo ese trabajo de granja era para practicar!$B$B¿Estás $glisto:lista; para ir en serio?$B$BMei Mei Zarpa Férrea, en el mercado, necesita algunas zanahorias para su estofado. ¿Y sabes quién las puede cultivar? ¡Nosotros!$B$BEnséñame lo que has aprendido y planta, cultiva y recoge cuatro hileras de zanahorias Jugoasaz.', '', '', '', '', '', 'Habla con: Granjero Yoon. Zona: Rancho Cantosol, Valle de los Cuatro Vientos.', 19865),
(31941, 'esES', 'Acaba con esos malos olores', 'Planta un calabacín de jade en el Rancho Cantosol. Puedes comprarle semillas al mercader Campo Fértil en El Mercado del Alcor.', 'El abuelo solía decirme: "cada semana un calabacín y adiós al olor vil".$B$B<Yoon olisquea el aire.>$B$BSip. Creo que ya ha pasado una semana. ¿Podrías ayudarme a plantar un calabacín de jade?', '', '', '', '', '', 'Vuelve con: Granjero Yoon. Zona: Rancho Cantosol, Valle de los Cuatro Vientos.', 19865),
(31942, 'esES', 'Temporada de melones', 'Planta un melón a rayas en el Rancho Cantosol. Puedes comprarle semillas al mercader Campo Fértil en El Mercado del Alcor.', '<El granjero Yoon mira al cielo y olisquea.>$B$BMmm...$B$B<Se lame la zarpa y la levanta, clava una uña del pie en el suelo y estudia la longitud de su sombra.>$B$BSip. Es temporada de melones.$B$B¿Podrías conseguirme unas semillas y ayudarme a plantar un melón a rayas?', '', '', '', '', '', 'Vuelve con: Granjero Yoon. Zona: Rancho Cantosol, Valle de los Cuatro Vientos.', 19865),
(31943, 'esES', '¿Qué buscas? Morujas.', 'Planta morujas en el Rancho Cantosol. Puedes comprarle semillas al mercader Campo Fértil en el Mercado del Alcor.', 'Ese joven de ahí, Andi, se convertirá en un granjero excepcional algún día. Lo sé solo con mirarlo.$B$BCreo que le plantaré algunas morujas. A los críos del encantan las morujas, será una bonita sorpresa.', '', '', '', '', '', 'Vuelve con: Granjero Yoon. Zona: Rancho Cantosol, Valle de los Cuatro Vientos.', 19865),
(31944, 'esES', 'Completa tu entrenamiento: La prueba final', 'Ve al Campo de Entrenamiento, en el Pico de la Serenidad y completa tu prueba final.', '$gBienvenido:Bienvenida;, $n. Ha llegado la hora de que completes la última etapa de tu entrenamiento. Dirígete al Campo de Entrenamiento para tu prueba final.', '', '', '', '', '', 'Vuelve con: Maestro Cenit. Zona: Santuario del Buey.', 19865),
(31945, 'esES', 'Aprender y cultivar VI: El voto de Gina', 'Planta y cosecha 1 cebolleta, y luego entrega 5 cebolletas a Gina Zarpa Fangosa.$b$bEl mercader Campo Fértil vende semillas de cebolleta en el Mercado del Alcor. Después de arar y cuidar de tu planta, tienes que esperar hasta el día siguiente para cosechar cebolletas maduras.', '¡Mi negocio está perdido! ¿Ves a todos los Zarpa Férrea en sus puestos de cocina?$b$bSus deliciosos platos atraen a muchos clientes al mercado, ¡pero se les han acabado las cebolletas!$b$bNo parece gran cosa, pero la cebolleta es un ingrediente culinario esencial. Sin ella, la comida es menos sabrosa, menos intensa y menos aromática.$b$bEsto es terrible. ¡No recibiré otro cargamento de cebolletas hasta la semana que viene!$b$bEspera un momento... Tú eres $ggranjero:granjera;, ¿no? ¿Puedes ayudarme?', '', '', '', '', '', 'Habla con: Gina Zarpa Fangosa. Zona: Mercado del Alcor, Valle de los Cuatro Vientos.', 19865),
(31946, 'esES', 'El voto de Mung-Mung III: El gran golpe de las zanahorias', 'Planta y cosecha 2 zanahorias Jugoasaz y luego entrega 10 zanahorias Jugoasaz a Mung-Mung.$b$bEl mercader Campo Fértil vende semillas de zanahoria Jugoasaz en el Mercado del Alcor. Después de arar y cuidar de tu planta, tienes que esperar hasta el día siguiente para cosechar zanahorias Jugoasaz maduras.', 'A Mung-Mung no le importa kién roba las zanahorias. ¡Solo le importa lo ke el señor Zarpa Fangosa jeringará a Mung-Mung kuando deskubra que su kosecha está perdida!$B$B<Mung-Mung se rasca la barbilla pensativo.>$B$B¡Espera! Mung-Mung tiene una idea brillante. Tú va y kultiva algunas zanahorias Jugoasaz. Luego, nosotros kogen tus zanahorias y fingen ke son las del señor Zarpa Fangosa.$B$B¡Eso es!', '', '', '', '', '', 'Vuelve con Mung-Mung. Zona: Casa de Haohan Zarpa Fangosa, Valle de los Cuatro Vientos.', 19865),
(31947, 'esES', 'Voto III del granjero Fung: el meollo del repollo', 'Planta y cosecha 3 repollos verdes y luego entrega 15 repollos verdes al granjero Fung.$b$bEl mercader Campo Fértil vende semillas de repollo verde en el Mercado del Alcor. Después de arar y cuidar de tu planta, tienes que esperar hasta el día siguiente para cosechar repollos verdes maduros.', '<El granjero Fung tiene una sonrisa radiante en la cara.>$B$B¡Gracias a ti he recuperado a mis preciados yaks! Desgraciadamente, he notado que el tiempo que han pasado asilvestrados los ha dejado un poco en los huesos.$B$BTienen que estar muertos de hambre, pero no alimento a mis mejores yaks con hierba normal y corriente.$B$BNo, $gseñor:señora;, solo comen los repollos más verdes y frondosos del valle.$B$BMi reservas no están en su mejor momento. Si me traes repollos para mis yaks, te recompensaré generosamente.', '', '', '', '', '', 'Vuelve con: El granjero Fung. Zona: Los Cultivos Florecientes en el Mercado del Alcor, Valle de los Cuatro Vientos.', 19865),
(31948, 'esES', 'El voto de Nana II: Las fuentes sagradas', 'Utiliza la jarra vacía en las Cataratas Doradas para recoger agua milenaria.', 'Has venido en un momento oportuno, $n. Estaba a punto de preparar una tanda de sirope de moruja.$b$b¿Alguna vez habías oído hablar de esa maravilla?$b$b¡Cada sorbo te quita diez años de la cara! ¿Por qué te crees que aún tengo este aspecto?$b$bA lo que iba: necesito un ingrediente especial, agua milenaria. Se puede recoger de la catarata que hay al norte.$b$bMe temo que el viaje es demasiado traicionero para una anciana como yo, pero si te haces con una jarra, te dejaré probar mi sirope.', '', '', '', '', '', 'Vuelve con: Nana Zarpa Fangosa. Zona: El Alcor, Valle de los Cuatro Vientos.', 19865),
(31949, 'esES', 'El voto de Nana III: Sirope de moruja', 'Planta y cosecha 3 morujas y luego entrega 15 morujas a Nana Zarpa Fangosa.$b$bEl mercader Campo Fértil vende semillas de moruja en el Mercado del Alcor. Después de arar y cuidar de tu planta, tienes que esperar hasta el día siguiente para cosechar morujas maduras.', '¡Ahora que tenemos el agua ya casi puedo saborear el frío sirope de moruja!$B$BSolo falta dar con algunas dulces morujas.$B$BLas moras de mi nieto han sido un completo fracaso esta temporada, así que habrá que encontrar una cosecha decente en otra parte.$B$BOye, ¿no tienes morujas en tu campo este año? ¿Qué tal si me traes unas cuantas de tu granja?$B$BSi tus moras están a la altura, ¡Nos prepararemos una buena cantidad del viejo zumo!', '', '', '', '', '', 'Vuelve con: Nana Zarpa Fangosa. Zona: El Alcor, Valle de los Cuatro Vientos.', 19865),
(31950, 'esES', 'Misión de seguimiento: trasladar a Dais a los PNJ', '', '', '', '', '', '', '', '', 19865),
(31951, 'esES', 'Gran maestra Aki', 'Derrota a Aki la Elegida en un duelo de mascotas.', 'Has peleado duro y bien contra los instructores de Azeroth. Hasta los grandes maestros han caído bajo tus astutas tácticas.$B$BTe espero en el Valle de la Flor Eterna, pues te has ganado el privilegio de afrontarme en combate. Ven, $n, y veamos si estás $ghecho:hecha; de la pasta necesaria para derrotarme.', '', '', 'Aki la Elegida', '', '', 'Habla con: Aki la Elegida.', 19865),
(31952, 'esES', 'Domadores de mascotas de duelo: Pandaria', 'Derrota a Hyuna de los Santuarios, a la granjera Nishi, a Mo''ruk, al Valiente Yon, al buscador Zusshi y al transitayermos Shu en duelos de mascotas.', 'Ahora debes enfrentarte a los domadores de mascotas más duros de todo Azeroth, $n. Viven en Pandaria, el campo de entrenamiento de los grandes maestros.$b$bHay seis grandes maestros que te quedan por derrotar: Hyuna de los Santuarios, en el Bosque de Jade; la granjera Nishi, en el Valle de los Cuatro Vientos; Mo''ruk, en la Espesura Krasarang; Valiente Yon, en la Cima Kun-Lai; el buscador Zusshi, en las Estepas de Tong Long, y el transitayermos Shu, en el Desierto del Pavor.$b$bSi crees que estás $gpreparado:preparada;, ¡busca a estos campeones y ponte a prueba contra ellos!', '', '', '', 'Tu desafío final espera.', 'Varzok', '', 19865),
(31953, 'esES', 'Gran maestra Hyuna', 'Derrota a Hyuna de los Santuarios en un duelo de mascotas.', '¿Pretendes luchar otra vez? Muy bien, así me fortaleceré para proteger mejor los lugares sagrados de mi gente.', '', '', '', '', '', 'Habla con: Hyuna de los Santuarios.', 19865),
(31954, 'esES', 'Gran maestro Mo''ruk', 'Derrota a Mo''ruk en un duelo de mascotas.', '¡Esta vez te machacaré yo! ¡Mira y verás!', '', '', '', '', '', 'Habla con: Mo''ruk.', 19865),
(31955, 'esES', 'Gran maestra Nishi', 'Derrota a la granjera Nishi en un duelo de mascotas.', 'Mis mascotas siguen ganando fuerza gracias a la tierra fértil sobre la que entrenamos. ¡No tienes la más mínima oportunidad!', '', '', '', '', '', 'Habla con: Granjera Nishi.', 19865),
(31956, 'esES', 'Gran maestro Yon', 'Derrota a Valiente Yon en un duelo de mascotas.', 'Si crees que voy a permitir que te hagas con otra victoria, estás muy $gequivocado:equivocada;. ¡Esta vez te derrotaré con mis habilidades superiores!', '', '', '', '', '', 'Habla con: Gran maestro Yon.', 19865),
(31957, 'esES', 'Gran maestro Shu', 'Derrota al transitayermos Shu en un duelo de mascotas.', 'Te adentras en el corazón del desierto para enfrentarte de nuevo a mí, solo para caer $gderrotado:derrotada; a manos de un gran maestro. Noble, pero $gestúpido:estúpida;.', '', '', '', '', '', 'Habla con: Transitayermos Shu.', 19865),
(31958, 'esES', 'Gran maestra Aki', 'Derrota a Aki la Elegida en un duelo de mascotas.', '¿Quieres probarte contra mí una vez más? Muy bien, luchemos.', '', '', '', '', '', 'Habla con: Aki la Elegida.', 19865),
(31959, 'esES', 'La táctica de la Emperatriz', 'Preséntate ante Malik el Indemne fuera del Corazón del Miedo.', 'La gran emperatriz Shek''zeer parece haber perdido la paciencia con nosotros. Acabamos de averiguar que un ejército enorme está formándose en las sombras del Corazón del Miedo, con órdenes de aplastar Klaxxi''vess.$B$BHemos sido afortunados por haber aguantado tanto tiempo, pero no podemos sobrevivir a un asedio de esta escala.$B$BDespertador, tu valor para nuestros esfuerzos ha sido incalculable. Ve y ocupa tu puesto en el campo de batalla entre los dechados.$b$b¡Te veré en el combate!', '', '', '', '', '', '', 19865),
(31960, 'esES', 'Tracking Event: Vote #1 Complete', '', '', '', '', '', '', '', '', 19865),
(31961, 'esES', 'Tracking Event: Vote #2 Complete', '', '', '', '', '', '', '', '', 19865),
(31962, 'esES', 'Tracking Event: Vote #3 Complete', '', '', '', '', '', '', '', '', 19865),
(31963, 'esES', 'Tracking Event: Vote #4 Complete', '', '', '', '', '', '', '', '', 19865),
(31964, 'esES', 'Tracking Event: Vote #5 Complete', '', '', '', '', '', '', '', '', 19865),
(31965, 'esES', 'Tracking Event: Vote #6 Complete', '', '', '', '', '', '', '', '', 19865),
(31966, 'esES', 'Domadores de mascotas de duelo: Cataclysm', 'Derrota a Brok, a Bordin Puñofirme y a Goz Malafuria en un duelo de mascotas.', 'Has derrotado a los mejores domadores de Rasganorte, pero necesitas más preparación antes de poder enfrentarte a los maestros de Pandaria. Entrena y perfecciona tus habilidades derrotando a estos domadores de élite: Brok, en el Monte Hyjal; Bordin Puñofirme, en Infralar y Goz Malafuria, en las Tierras Altas Crepusculares.$B$BUna vez que los hayas superado, podrás viajar a Pandaria para enfrentarte al último desafío.', '', '', 'Audrey Burnhep', '¿Podrás con ella?', 'Audrey Burnhep', '', 19865),
(31967, 'esES', 'Domadores de mascotas de duelo: Cataclysm', 'Derrota a Brok, a Bordin Puñofirme y a Goz Malafuria en un duelo de mascotas.', 'Rasganorte se ha rendido ante ti, pero aún no estás $glisto:lista; para enfrentarte a los grandes maestros de Pandaria. Derrota a estos domadores para fortalecer tu voluntad en los desafíos que te esperan: Brok, en el Monte Hyjal; Bordin Puñofirme, en Infralar y a Goz Malafuria en las Tierras Altas Crepusculares.$B$BSolo tras derrotarlos estarás $gpreparado:preparada; para viajar a Pandaria.', '', '', 'Varzok', '¿Crees que estarás a la altura del siguiente desafío?', 'Varzok', '', 19865),
(31969, 'esES', 'Priorities Tracking', '', '', '', '', '', '', '', '', 19865),
(31970, 'esES', 'Gran maestro Obalis', 'Derrota a Obalis en un duelo de mascotas.', '¿Crees que estás $glisto:lista; para desafiar a Pandaria? ¿Realmente crees que puedes vencer a los domadores más poderosos de todo Azeroth?$B$BSeré yo quien lo juzgue, $r. Enfréntate a mí en la cima de la Presa Vir''naal, en Uldum, y veremos si estás $gpreparado:preparada; de verdad.', '', '', 'Obalis', '', '', 'Habla con: Obalis.', 19865),
(31971, 'esES', 'Gran maestro Obalis', 'Derrota a Obalis en un duelo de mascotas.', 'Veo que $gel glorioso domador:la gloriosa domadora; regresa para medirse conmigo una vez más. Muy bien. Acepto tu desafío.', '', '', '', '', '', 'Habla con: Obalis.', 19865),
(31972, 'esES', 'Brok', 'Derrota a Brok en un duelo de mascotas.', 'Aún no comprendo lo suficientemente bien la situación de estas criaturas como para poder ayudarlas. Es posible que otro duelo fortalezca nuestros lazos.', '', '', '', '', '', 'Habla con: Brok.', 19865),
(31973, 'esES', 'Bordin Puñofirme', 'Derrota a Bordin Puñofirme en un duelo de mascotas.', 'Los nativos me han enseñado la fuerza de la tierra. Conozco su resistencia imperecedera. ¡Luchemos una vez más y verás que mi fuerza es mayor que nunca!', '', '', '', '', '', 'Habla con: Bordin Puñofirme.', 19865),
(31974, 'esES', 'Goz Malafuria', 'Derrota a Goz Malafuria en un duelo de mascotas.', 'El poder del crepúsculo corre por mis venas. ¡Soy un dios! ¡No puedes esperar derrotarme!', '', '', '', '', '', 'Habla con: Goz Malafuria.', 19865),
(31975, 'esES', 'El regreso de los campeones', 'Ve a ver a Audrey Burnhep en Ventormenta.', 'Si quieres mi opinión, deberías estar en Terrallende, con los demás ases. ¿Por qué no vuelves a ver a Audrey Burnhep, en Ventormenta, para ver cuál es el siguiente paso de tu carrera como $gdomador:domadora;?', '', '', '', '', '', '', 19865),
(31976, 'esES', 'El regreso de los campeones', 'Ve a ver a Audrey Burnhep en Ventormenta.', 'Cada vez se habla más de tus hazañas. Te sugiero que vuelvas a ver a tu entrenadora, Audrey Burnhep, para que te aconseje.', '', '', '', '', '', '', 19865),
(31977, 'esES', 'El regreso de los campeones', 'Ve a ver a Varzok en Orgrimmar.', 'Si quieres mi opinión, deberías estar en Terrallende, con los demás ases. ¿Por qué no vuelves a ver a Varzok, en Orgrimmar, para ver cuál es el siguiente paso de tu carrera como $gdomador:domadora;?', '', '', '', '', '', '', 19865),
(31978, 'esES', '¡Prioridades!', 'Encuentra 6 barricas de birramiel en el Claro Almíbar.', '¡Mira este desastre! ¡Toda esa cerveza desperdiciada!$b$bTaran Zhu nos advirtió de que no habláramos con forasteros, pero necesito toda la ayuda que pueda encontrar.$B$BNos dirigíamos a Floralba para entregar nuestra cerveza cuando empezó la lucha. ¡Ahora la hemos perdido toda!$B$B¿Quieres compensarnos? Puede que encuentres algunas barricas de birramiel que no se hayan roto. Así no estaría todo perdido.', '', '', '', '', '', 'Vuelve con: Ellie Zarpa Melosa. Zona: Poblado Almíbar.', 19865),
(31980, 'esES', 'El regreso de los campeones', 'Ve a ver a Varzok en Orgrimmar.', 'Cada vez se habla más de tus hazañas. Te sugiero que vuelvas a ver a tu entrenador, Varzok, para que te aconseje.', '', '', '', '', '', '', 19865),
(31981, 'esES', 'Expectativas superadas', 'Ve a ver a Audrey Burnhep en Ventormenta.', 'Ve a ver a tu entrenadora, Audrey Burnhep, en Ventormenta. A lo mejor ella puede encontrarte desafíos más... dignos...', '', '', '', '', '', '', 19865),
(31982, 'esES', 'Expectativas superadas', 'Ve a ver a Varzok en Orgrimmar.', 'Ve a ver a tu entrenador, Varzok, en Orgrimmar. A lo mejor él puede encontrarte desafíos más... dignos...', '', '', '', '', '', '', 19865),
(31983, 'esES', 'Un breve respiro', 'Ve a ver a Varzok en Orgrimmar.', 'No está mal, para ser $gun:una; $r. Ahora vuelve a Orgrimmar y habla con el tosco Varzok. A lo mejor puede enviarte a algún lugar muy lejos de mi familia.', '', '', '', '', '', '', 19865),
(31984, 'esES', 'Un breve respiro', 'Ve a ver a Audrey Burnhep en Ventormenta.', '¡Bien hecho! ¡Estupendo! Si quieres, vuelve a ver a la señorita Audrey Burnhep en Ventormenta.$b$bAh, y dale recuerdos de mi parte. Es una joven hermosa a la que le vendría bien la compañía de un luchador ejemplar como yo.', '', '', '', '', '', '', 19865),
(31985, 'esES', 'El regreso triunfante', 'Ve a ver a Audrey Burnhep en Ventormenta.', 'Ya estás $gpreparado:preparada;, como ordenó tu entrenador. Vuelve a Ventormenta y habla con Audrey Burnhep. Ella te guiará.', '', '', '', '', '', '', 19865),
(31986, 'esES', 'El regreso triunfante', 'Ve a ver a Varzok en Orgrimmar.', 'Ya estás $gpreparado:preparada;, como ordenó tu entrenador. Vuelve a Orgrimmar y habla con Varzok. Él te guiará.', '', '', '', '', '', '', 19865),
(31989, 'esES', 'El Pico de la Serenidad: Completa el entrenamiento', 'Usa Peregrinaje zen para viajar al Pico de la Serenidad y habla con el maestro Cenit en el Santuario del Buey cuando llegues.', 'Ha llegado el momento de que vuelvas al Pico de la Serenidad y completes tu entrenamiento. Usa Peregrinaje zen para ir allí y habla con el maestro Cenit cuando llegues.', '', '', '', '', '', 'Habla con: Maestro Cenit. Zona: Santuario del Buey.', 19865),
(31990, 'esES', 'Audrey Burnhep', 'Ve a ver a Audrey Burnhep en Ventormenta.', 'Me temo que ya no tengo nada más que enseñarte, $n. Sin embargo, ¡tu viaje como $ginstructor:instructora; está lejos de llegar a su fin!$B$BVe a ver a Audrey Burnhep en Ventormenta. Está en contacto con algunos de los mejores instructores de Azeroth y te ayudará a ir más lejos.', '', '', 'Grady Bannson', '', '', '', 19865),
(31991, 'esES', 'Gran maestro Zusshi', 'Derrota al buscador Zusshi en un duelo de mascotas.', 'Sabía que volverías a enfrentarte a mí. Veamos quién es el más sabio en el arte del duelo.', '', '', '', '', '', 'Habla con: Buscador Zusshi.', 19865),
(31992, 'esES', '[FLAG] Dread Wastes Buff Bitflag - Enhancement 01', '', '', '', '', '', '', '', '', 19865),
(31993, 'esES', '[FLAG] Dread Wastes Buff Bitflag - Enhancement 02', '', '', '', '', '', '', '', '', 19865),
(31994, 'esES', '[FLAG] Dread Wastes Buff Bitflag - Enhancement 03', '', '', '', '', '', '', '', '', 19865),
(31995, 'esES', '[FLAG] Dread Wastes Buff Bitflag - Augmentation 01', '', '', '', '', '', '', '', '', 19865),
(31996, 'esES', '[FLAG] Dread Wastes Buff Bitflag - Augmentation 02', '', '', '', '', '', '', '', '', 19865),
(31997, 'esES', '[FLAG] Dread Wastes Buff Bitflag - Augmentation 03', '', '', '', '', '', '', '', '', 19865),
(31999, 'esES', 'La orden de Nazgrim', 'Preséntate ante el general Nazgrim en la Pista de Aterrizaje Armafuerte, en El Bosque de Jade.', 'Tienes una base de operaciones muy cómoda, no hay soldados de la Alianza en millas a la redonda y cuentas con algunos veteranos de la Horda. Parece que ha llegado la hora de pintar de rojo este continente.$B$BEl general Nazgrim debería saber por dónde empezar.', '', '', '', '', '', '', 19865),
(32001, 'esES', 'Un desafío digno: Sha del odio', 'Completa el Monasterio del Shadopan en modo desafío.', '$n, necesito que reúnas un grupo sereno y lo lleves al Monasterio del Shadopan. Activa el orbe de contendiente que hay dentro y rescata a Taran Zhu del Sha del odio.$B$BVuelve aquí cuando hayas completado este desafío y te recompensaré generosamente.', '', '', '', '', '', 'Vuelve con: Contendiente Soong. Zona: Santuario de las Siete Estrellas, Valle de la Flor Eterna.', 19865),
(32008, 'esES', 'Audrey Burnhep', 'Ve a ver a Audrey Burnhep en Ventormenta.', '¡Saludos, $n! Mi nombre es Audrey Burnhep. He oído hablar mucho de ti últimamente. ¡Te estás convirtiendo en $gtodo un domador:toda una domadora;!$B$BDeberías venir a verme a Ventormenta. Conozco a algunos de los mejores domadores de todo Azeroth y puedo ayudarte a llegar mucho más lejos.', '', '', 'Audrey Burnhep', '', '', '', 19865),
(32009, 'esES', 'Varzok', 'Ve a ver a Varzok en Orgrimmar.', 'Lok''tar, $n. Me llamo Varzok. Últimamente he oído hablar mucho de tus hazañas como $gdomador:domadora; y me gustaría presentarte a instructores de todo Azeroth para que puedas seguir perfeccionando tus habilidades.$B$BVen a verme a Orgrimmar para que podamos empezar.', '', '', 'Varzok', '', '', '', 19865),
(32010, 'esES', 'Una tarea celestial', 'Has ganado reputación de Venerable con el Loto Dorado.', '¿Conoces a los Augustos Celestiales? Yu''lon, Chi-Ji, Xuen y Niuzao guardan los cuatro rincones de Pandaria.$B$BTambién te guardan a ti.$B$BSu conocimiento es muy antiguo y poderoso. A aquellos que cuentan con su favor les otorgan gran poder.$B$BPuedes intentar ganarte su confianza, pero te necesitan para una tarea mucho más importante.$B$BEl Valle de la Flor Eterna está en peligro. Antes que nada, todos debemos defender el valle. Luego, podremos centrarnos en los Augustos Celestiales.', '', '', '', '', '', 'Habla con: Sabia Flor de Loto. Zona: Santuario de las Dos Lunas, Valle de la Flor Eterna.', 19865),
(32011, 'esES', 'Una tarea celestial', 'Has ganado reputación de Venerable con el Loto Dorado.', '¿Conoces a los Augustos Celestiales? Yu''lon, Chi-Ji, Xuen y Niuzao guardan los cuatro rincones de Pandaria.$B$BTambién te guardan a ti.$B$BSu conocimiento es muy antiguo y poderoso. A aquellos que cuentan con su favor les otorgan gran poder.$B$BPuedes intentar ganarte su confianza, pero te necesitan para una tarea mucho más importante.$B$BEl Valle de la Flor Eterna está en peligro. Antes que nada, todos debemos defender el valle. Luego, podremos centrarnos en los Augustos Celestiales.', '', '', '', '', '', 'Habla con: Sabio Corazón Albo. Zona: Santuario de las Siete Estrellas, Valle de la Flor Eterna.', 19865),
(32012, 'esES', 'Kovok tracking [GROWING]', '', '', '', '', '', '', '', '', 19865),
(32016, 'esES', 'Talismanes ancestrales de buena fortuna', 'Consigue 90 talismanes de buena fortuna inferiores.', 'Saludos, $n. Tengo el privilegio de ofrecerte una oportunidad excelente. A través de los siglos, hemos perfeccionando un método con el que se pueden manipular las mismísimas leyes de la fortuna. Con un talismán ancestral de buena fortuna, tus bolsillos se llenarán de objetos de valor mucho más a menudo.', '', '', '', '', '', 'Vuelve con: Ancestro Lin. Zona: Santuario de las Siete Estrellas, Valle de la Flor Eterna.', 19865),
(32017, 'esES', 'Talismanes ancestrales de buena fortuna', 'Consigue 90 talismanes de buena fortuna inferiores.', 'Saludos, $n. Tengo el privilegio de ofrecerte una oportunidad excelente. A través de los siglos, hemos perfeccionando un método con el que se pueden manipular las mismísimas leyes de la fortuna. Con un talismán ancestral de buena fortuna, tus bolsillos se llenarán de objetos de valor mucho más a menudo.', '', '', '', '', '', 'Vuelve con: Ancestro Liao. Zona: Santuario de las Dos Lunas, Valle de la Flor Eterna.', 19865),
(32018, 'esES', 'Le llamaban... Cerveza de Trueno', 'Habla con Chen Cerveza de Trueno en las Granjas Pie Atronador, en el Valle de los Cuatro Vientos.', 'Hace unos días llegó a la ciudad un pandaren poco común. Contó historias más fabulosas que las de Pan, bebió el doble que Lee y me dio una paliza delante de todos. Y mientras su pequeña sobrina se reía de nosotros.$B$BFue increíble.$B$BDijeron que iban al Valle de los Cuatro Vientos. ¡Deberías reunirte con él! Solo... ten cuidado con su derechazo.', '', '', '', '', '', '', 19865),
(32019, 'esES', 'Lo llaman... Cerveza de Trueno', 'Habla con Chen Cerveza de Trueno en las Granjas Pie Atronador, en el Valle de los Cuatro Vientos.', 'Las cosas no han sido siempre así, $r. Ah, no, antes eran mucho, mucho peores. No hace ni tres semanas nos asediaron unos bandidos saurok. Nos robaron el jade, nos arruinaron las provisiones y asustaron a nuestros cachorros.$b$bNos hacía falta un héroe, y un héroe es lo que recibimos.$b$bExpulsó a los delincuentes, derrotó a su líder y nos devolvió el jade robado. Lo único que nos pidió a cambio fue un viaje en dragón para su sobrina.$b$bNunca pude darle las gracias. Si te diriges al Valle de los Cuatro Vientos, ¿te importa transmitirle nuestro agradecimiento?', '', '', '', '', '', '', 19865),
